import crypto from 'crypto';
import path from 'path';
import { Router, type Request, type Response } from 'express';
import { z } from 'zod/v3';
import { createLogger } from '../utils/logger';
import type {
  BundleFile,
  BundleMetadata,
  BundleStore,
} from '../services/BundleStore';
import type { SupabaseAuthService } from '../services/SupabaseAuthService';
import { errorMessage } from '../utils/errorMessage';
import { DEFAULT_PROTOTYPE_HOST_URL } from '../config/proxy';

const log = createLogger('PrototypeHostRouter');

const RIVET_SOCIAL_IMAGE_URL = 'https://rivet.design/images/rivet-social.png';
const RIVET_DEFAULT_SHARE_DESCRIPTION =
  'Built with Rivet — the visual editor for design';

const SAFE_ID_PATTERN = /^[A-Za-z0-9_-]+$/;
const SHARE_NAME_ATTEMPT_LIMIT = 25;
const SHARE_SUFFIX_ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';
const SHARE_SUFFIX_LENGTH = 6;
const SHARE_SLUG_MAX_LENGTH = 48;
const SHARE_TITLE_MAX_LENGTH = 200;
const SHARE_SLUG_FALLBACK = 'prototype';
const RENDER_PR_PREVIEW_HOST_PATTERN =
  /^rivet-prototype-host-pr-\d+\.onrender\.com$/;

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.avif': 'image/avif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
  '.glb': 'model/gltf-binary',
  '.gltf': 'model/gltf+json',
  '.txt': 'text/plain; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.wasm': 'application/wasm',
};

const bundleFileSchema = z.object({
  path: z.string().min(1),
  content: z.string(),
});

const publishBodySchema = z.object({
  files: z.array(bundleFileSchema).min(1),
  title: z.string().max(SHARE_TITLE_MAX_LENGTH).optional(),
});

export interface PrototypeHostDeps {
  store: BundleStore;
  auth: SupabaseAuthService;
  publicBaseUrl?: string;
  maxBundleBytes?: number;
}

const injectBaseHref = (html: string, baseHref: string): string => {
  if (/<base\s/i.test(html)) return html;
  const tag = `<base href="${baseHref.replace(/"/g, '&quot;')}">`;
  const headMatch = /<head[^>]*>/i.exec(html);
  if (headMatch) {
    const insertAt = headMatch.index + headMatch[0].length;
    return html.slice(0, insertAt) + tag + html.slice(insertAt);
  }
  const doctypeMatch = /<!doctype[^>]*>/i.exec(html);
  if (doctypeMatch) {
    const insertAt = doctypeMatch.index + doctypeMatch[0].length;
    return html.slice(0, insertAt) + tag + html.slice(insertAt);
  }
  return tag + html;
};

const injectSocialMeta = (
  html: string,
  args: { title: string; url: string },
): string => {
  if (/property="og:title"/i.test(html)) {
    return html;
  }

  const escapedTitle = args.title
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;');
  const escapedUrl = args.url.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
  const escapedDesc = RIVET_DEFAULT_SHARE_DESCRIPTION.replace(
    /&/g,
    '&amp;',
  ).replace(/"/g, '&quot;');
  const tags = [
    `<meta property="og:type" content="website" />`,
    `<meta property="og:url" content="${escapedUrl}" />`,
    `<meta property="og:title" content="${escapedTitle}" />`,
    `<meta property="og:description" content="${escapedDesc}" />`,
    `<meta property="og:image" content="${RIVET_SOCIAL_IMAGE_URL}" />`,
    `<meta name="twitter:card" content="summary_large_image" />`,
    `<meta name="twitter:url" content="${escapedUrl}" />`,
    `<meta name="twitter:title" content="${escapedTitle}" />`,
    `<meta name="twitter:description" content="${escapedDesc}" />`,
    `<meta name="twitter:image" content="${RIVET_SOCIAL_IMAGE_URL}" />`,
  ].join('\n  ');

  const headMatch = /<head[^>]*>/i.exec(html);
  if (headMatch) {
    const insertAt = headMatch.index + headMatch[0].length;
    return (
      html.slice(0, insertAt) + '\n  ' + tags + '\n' + html.slice(insertAt)
    );
  }
  return tags + '\n' + html;
};

const extractBearer = (req: Request): string | null => {
  const header = req.headers['authorization'];
  if (typeof header === 'string' && header.startsWith('Bearer ')) {
    return header.slice(7);
  }
  const rivetToken = req.headers['x-rivet-auth-token'];
  return typeof rivetToken === 'string' && rivetToken.length > 0
    ? rivetToken
    : null;
};

const normalizeAssetPath = (raw: unknown): string => {
  if (Array.isArray(raw)) return raw.join('/');
  if (typeof raw === 'string') return raw;
  return '';
};

const createShareSuffix = (): string => {
  let suffix = '';
  for (let i = 0; i < SHARE_SUFFIX_LENGTH; i += 1) {
    const index = crypto.randomInt(SHARE_SUFFIX_ALPHABET.length);
    suffix += SHARE_SUFFIX_ALPHABET[index];
  }
  return suffix;
};

const slugifyShareTitle = (title?: string): string => {
  const slug = (title ?? '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-')
    .slice(0, SHARE_SLUG_MAX_LENGTH)
    .replace(/-+$/g, '');
  return slug || SHARE_SLUG_FALLBACK;
};

const createShareNameCandidate = (title?: string): string => {
  const slug = slugifyShareTitle(title);
  return `${slug}-${createShareSuffix()}`;
};

const normalizePublicBaseUrl = (rawBaseUrl?: string): string => {
  const baseUrl = rawBaseUrl?.trim() || DEFAULT_PROTOTYPE_HOST_URL;
  return baseUrl.replace(/\/+$/, '');
};

const getHeaderValue = (raw: string | string[] | undefined): string | null => {
  if (Array.isArray(raw)) {
    return raw[0] ?? null;
  }
  return raw ?? null;
};

const getFirstForwardedValue = (
  raw: string | string[] | undefined,
): string | null => {
  const value = getHeaderValue(raw)?.split(',')[0]?.trim();
  return value ? value : null;
};

const getRenderPreviewOrigin = (req: Request): string | null => {
  const hostHeader =
    getFirstForwardedValue(req.headers['x-forwarded-host']) ??
    getFirstForwardedValue(req.headers.host);
  if (!hostHeader) {
    return null;
  }

  const hostName = hostHeader.toLowerCase().replace(/:\d+$/, '');
  if (!RENDER_PR_PREVIEW_HOST_PATTERN.test(hostName)) {
    return null;
  }

  return `https://${hostName}`;
};

const resolvePublicBaseUrl = (
  req: Request,
  configuredPublicBaseUrl: string,
): string => {
  if (configuredPublicBaseUrl !== DEFAULT_PROTOTYPE_HOST_URL) {
    return configuredPublicBaseUrl;
  }

  return getRenderPreviewOrigin(req) ?? configuredPublicBaseUrl;
};

const createShareName = async (
  store: BundleStore,
  reservedShareNames: Set<string>,
  files: BundleFile[],
  metadata: Omit<BundleMetadata, 'shareName'>,
): Promise<string> => {
  for (let attempt = 0; attempt < SHARE_NAME_ATTEMPT_LIMIT; attempt += 1) {
    const candidate = createShareNameCandidate(metadata.title);
    if (reservedShareNames.has(candidate)) {
      continue;
    }
    reservedShareNames.add(candidate);
    try {
      const isStored = await store.putIfAbsent(candidate, files, {
        ...metadata,
        shareName: candidate,
      });
      if (isStored) {
        return candidate;
      }
    } catch (err) {
      reservedShareNames.delete(candidate);
      throw err;
    }
    reservedShareNames.delete(candidate);
  }
  throw new Error('Unable to allocate a unique share name.');
};

export const createPrototypeHostRouter = (deps: PrototypeHostDeps): Router => {
  const router = Router();
  const maxBundleBytes = deps.maxBundleBytes ?? 25 * 1024 * 1024;
  const configuredPublicBaseUrl = normalizePublicBaseUrl(deps.publicBaseUrl);
  const reservedShareNames = new Set<string>();

  router.get('/health', (_req, res) => {
    res.json({ ok: true });
  });

  router.post('/publish', async (req, res) => {
    const token = extractBearer(req);
    if (!token) {
      res.status(401).json({
        errorCode: 'AUTH_REQUIRED',
        message: 'Please run `rivet login` to deploy a prototype.',
      });
      return;
    }
    const user = await deps.auth.verifyToken(token);
    if (!user) {
      res.status(401).json({
        errorCode: 'AUTH_INVALID',
        message: 'Your session may have expired. Run `rivet login` again.',
      });
      return;
    }

    const parsed = publishBodySchema.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: parsed.error.message,
      });
      return;
    }

    const files: BundleFile[] = parsed.data.files;
    const totalBytes = files.reduce(
      (sum, f) => sum + Math.ceil((f.content.length * 3) / 4),
      0,
    );
    if (totalBytes > maxBundleBytes) {
      res.status(413).json({
        errorCode: 'BUNDLE_TOO_LARGE',
        message: `Prototype bundle exceeds the ${Math.round(
          maxBundleBytes / (1024 * 1024),
        )}MB limit.`,
      });
      return;
    }
    if (!files.some((f) => f.path === 'index.html')) {
      res.status(400).json({
        errorCode: 'BUNDLE_MISSING_INDEX',
        message: 'Bundle must contain an index.html at its root.',
      });
      return;
    }

    let deployId: string | null = null;
    try {
      const title = parsed.data.title?.trim() || undefined;
      deployId = await createShareName(deps.store, reservedShareNames, files, {
        title,
        createdAt: new Date().toISOString(),
      });
    } catch (err) {
      log.error(`publish failed for user ${user.id}`, err);
      res.status(500).json({
        errorCode: 'PUBLISH_FAILED',
        message: errorMessage(err, 'Failed to store bundle.'),
      });
      return;
    } finally {
      if (deployId) {
        reservedShareNames.delete(deployId);
      }
    }

    const publicBaseUrl = resolvePublicBaseUrl(req, configuredPublicBaseUrl);
    const shareUrl = `${publicBaseUrl}/share/${deployId}/`;
    log.info(`Published prototype ${deployId} for user ${user.id}`);
    res.json({ deployId, shareUrl });
  });

  const serve = async (
    req: Request,
    res: Response,
    deployId: string,
    assetPath: string,
    routePrefix: 'p' | 'share',
  ): Promise<void> => {
    if (!SAFE_ID_PATTERN.test(deployId)) {
      res.status(404).send('Not found');
      return;
    }
    if (!(await deps.store.has(deployId))) {
      res.status(404).send('Not found');
      return;
    }

    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'no-store');

    const cleanPath = assetPath.replace(/^\/+/, '');
    const wantsIndex = cleanPath === '' || cleanPath.endsWith('/');
    const baseHref = `/${routePrefix}/${deployId}/`;

    const serveIndex = async (): Promise<void> => {
      const html = await deps.store.read(deployId, 'index.html');
      if (!html) {
        res.status(404).send('Not found');
        return;
      }
      const publicBaseUrl = resolvePublicBaseUrl(req, configuredPublicBaseUrl);
      const shareUrl = `${publicBaseUrl}/${routePrefix}/${deployId}/`;
      const metadata = await deps.store.getMetadata(deployId);
      const title = metadata?.title || 'Rivet Prototype';
      let result = html.toString('utf8');
      result = injectSocialMeta(result, { title, url: shareUrl });
      result = injectBaseHref(result, baseHref);
      res.status(200).setHeader('Content-Type', MIME['.html']).send(result);
    };

    if (wantsIndex) {
      await serveIndex();
      return;
    }

    const decoded = decodeURIComponent(cleanPath);
    const body = await deps.store.read(deployId, decoded);
    if (!body) {
      await serveIndex();
      return;
    }
    const ext = path.extname(decoded).toLowerCase();
    res
      .status(200)
      .setHeader('Content-Type', MIME[ext] || 'application/octet-stream')
      .send(body);
  };

  router.get('/p/:deployId', async (req, res) => {
    await serve(req, res, req.params.deployId, '', 'p');
  });
  router.get('/p/:deployId/{*assetPath}', async (req, res) => {
    await serve(
      req,
      res,
      req.params.deployId,
      normalizeAssetPath((req.params as Record<string, unknown>).assetPath),
      'p',
    );
  });
  router.get('/share/:shareName', async (req, res) => {
    await serve(req, res, req.params.shareName, '', 'share');
  });
  router.get('/share/:shareName/{*assetPath}', async (req, res) => {
    await serve(
      req,
      res,
      req.params.shareName,
      normalizeAssetPath((req.params as Record<string, unknown>).assetPath),
      'share',
    );
  });

  return router;
};
